// Hire keys, checked against the vectors robot/tools/hire-key.mjs writes, and
// the anchored clock (docs/adr/0002).
#include <stdio.h>
#include <string.h>
#include <unity.h>

#include "hire_key.h"
#include "hire_key_vectors.h"  // generated by scripts/gen_vectors.py

using namespace mulligan;

namespace {
size_t fromHex(const char* hex, uint8_t* out, size_t cap) {
  const size_t n = strlen(hex) / 2;
  TEST_ASSERT_TRUE(n <= cap);
  for (size_t i = 0; i < n; i++) {
    unsigned v;
    sscanf(hex + 2 * i, "%2x", &v);
    out[i] = static_cast<uint8_t>(v);
  }
  return n;
}

uint8_t publicKey[32];
uint8_t key[128];

const vectors::Case& findCase(const char* name) {
  for (unsigned i = 0; i < vectors::kCaseCount; i++) {
    if (strcmp(vectors::kCases[i].name, name) == 0) return vectors::kCases[i];
  }
  TEST_FAIL_MESSAGE(name);
  return vectors::kCases[0];
}

size_t loadCase(const char* name) { return fromHex(findCase(name).keyHex, key, sizeof key); }
}  // namespace

void setUp() { fromHex(vectors::kPublicKeyHex, publicKey, 32); }
void tearDown() {}

static void test_every_vector_gives_its_expected_result() {
  TEST_ASSERT_TRUE(vectors::kCaseCount >= 15);
  for (unsigned i = 0; i < vectors::kCaseCount; i++) {
    const vectors::Case& c = vectors::kCases[i];
    const size_t n = fromHex(c.keyHex, key, sizeof key);
    const KeyCheck got = checkHireKey(n ? key : nullptr, n, publicKey, vectors::kRobotSerial, c.now);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(c.expect, keyCheckName(got), c.name);
  }
}

static void test_every_vector_decodes_to_its_fields() {
  for (unsigned i = 0; i < vectors::kCaseCount; i++) {
    const vectors::Case& c = vectors::kCases[i];
    const size_t n = fromHex(c.keyHex, key, sizeof key);
    HireKey k;
    TEST_ASSERT_EQUAL_MESSAGE(n == kHireKeyLength, decodeHireKey(key, n, k), c.name);
    if (!c.hasFields) continue;
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(c.version, k.version, c.name);
    TEST_ASSERT_EQUAL_MEMORY_MESSAGE(c.serial, k.serial, 4, c.name);
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(c.start, k.start, c.name);
    TEST_ASSERT_EQUAL_UINT32_MESSAGE(c.end, k.end, c.name);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(c.bay, k.bay, c.name);
  }
}

static void test_anchored_clock_is_unknown_until_anchored_and_then_counts() {
  AnchoredClock clock;
  uint32_t now = 0;
  TEST_ASSERT_FALSE(clock.now(5000, now));
  clock.offerAnchor(1000000, 5000);
  TEST_ASSERT_TRUE(clock.now(5000, now));
  TEST_ASSERT_EQUAL_UINT32(1000000, now);
  TEST_ASSERT_TRUE(clock.now(5000 + 61999, now));
  TEST_ASSERT_EQUAL_UINT32(1000061, now);
  clock.offerAnchor(2000000, 9000);  // a second anchor is ignored
  TEST_ASSERT_TRUE(clock.now(5000, now));
  TEST_ASSERT_EQUAL_UINT32(1000000, now);
}

static void test_anchored_clock_survives_the_millisecond_counter_wrapping() {
  AnchoredClock clock;
  clock.offerAnchor(100, 0xFFFFFC18u);  // 1000 ms before the wrap
  uint32_t now = 0;
  TEST_ASSERT_TRUE(clock.now(2000, now));
  TEST_ASSERT_EQUAL_UINT32(103, now);
}

static void test_lock_unlocks_with_a_good_key_and_anchors_the_clock() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  lock.connected();
  TEST_ASSERT_FALSE(lock.unlocked(0));
  const size_t n = loadCase("ok_mid_hire");
  TEST_ASSERT_EQUAL_STRING("ok", keyCheckName(lock.unlock(key, n, 1000)));
  TEST_ASSERT_TRUE(clock.anchored());
  TEST_ASSERT_TRUE(lock.unlocked(1000));
  TEST_ASSERT_EQUAL_UINT8(3, lock.key().bay);
}

static void test_lock_locks_when_the_hire_ends() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  lock.connected();
  const size_t n = loadCase("ok_mid_hire");  // a one-hour hire
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 0));
  TEST_ASSERT_TRUE(lock.unlocked(3599999));
  TEST_ASSERT_FALSE(lock.unlocked(3600000));
  TEST_ASSERT_FALSE(lock.unlocked(0));  // stays locked
  // The same key written again is now expired.
  TEST_ASSERT_EQUAL_STRING("expired", keyCheckName(lock.unlock(key, n, 3600000)));
}

static void test_a_bad_key_does_not_anchor_the_clock_and_locks() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  lock.connected();
  const char* bad[] = {"bad_signature_bay_changed", "bad_signature_other_signer", "wrong_serial", "bad_version_2",
                       "bad_length_77"};
  for (const char* name : bad) {
    const size_t n = loadCase(name);
    TEST_ASSERT_NOT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 0));
    TEST_ASSERT_FALSE_MESSAGE(clock.anchored(), name);
  }
  // A good key, then a bad one: the bad write locks it again.
  size_t n = loadCase("ok_mid_hire");
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 0));
  n = loadCase("bad_signature_signature_changed");
  TEST_ASSERT_EQUAL(KeyCheck::BadSignature, lock.unlock(key, n, 10));
  TEST_ASSERT_FALSE(lock.unlocked(10));
}

static void test_a_later_key_is_checked_against_the_anchored_time() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  lock.connected();
  // Anchor on the wide-window key, which starts in 1970: the 2027 hire is not
  // due yet by this clock.
  size_t n = loadCase("ok_wide_window_bay_255");
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 0));
  n = loadCase("ok_mid_hire");
  TEST_ASSERT_EQUAL_STRING("not_yet", keyCheckName(lock.unlock(key, n, 1000)));
  TEST_ASSERT_FALSE(lock.unlocked(1000));
}

static void test_explicit_lock() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  lock.connected();
  const size_t n = loadCase("ok_at_start");
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 0));
  lock.lock();
  TEST_ASSERT_FALSE(lock.unlocked(1));
}

static void test_result_codes_on_the_wire() {
  // docs/adr/0005: what reading Unlock returns.
  TEST_ASSERT_EQUAL_UINT8(0, static_cast<uint8_t>(KeyCheck::Ok));
  TEST_ASSERT_EQUAL_UINT8(1, static_cast<uint8_t>(KeyCheck::BadLength));
  TEST_ASSERT_EQUAL_UINT8(2, static_cast<uint8_t>(KeyCheck::BadVersion));
  TEST_ASSERT_EQUAL_UINT8(3, static_cast<uint8_t>(KeyCheck::BadSignature));
  TEST_ASSERT_EQUAL_UINT8(4, static_cast<uint8_t>(KeyCheck::WrongSerial));
  TEST_ASSERT_EQUAL_UINT8(5, static_cast<uint8_t>(KeyCheck::NotYet));
  TEST_ASSERT_EQUAL_UINT8(6, static_cast<uint8_t>(KeyCheck::Expired));
  TEST_ASSERT_EQUAL_UINT8(7, static_cast<uint8_t>(KeyCheck::NoClock));
}

static void test_a_disconnect_forgets_the_key_and_its_result() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  lock.connected();
  const size_t n = loadCase("ok_mid_hire");
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 0));
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.lastResult());
  TEST_ASSERT_TRUE(lock.unlocked(10));

  lock.disconnected();
  TEST_ASSERT_FALSE(lock.unlocked(20));
  TEST_ASSERT_EQUAL(KeyCheck::BadLength, lock.lastResult());

  // The next phone, or the same one back: locked until it writes a key.
  lock.connected();
  TEST_ASSERT_FALSE(lock.unlocked(30));
  TEST_ASSERT_EQUAL(KeyCheck::BadLength, lock.lastResult());
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 40));  // same key, still inside the hire
  TEST_ASSERT_TRUE(lock.unlocked(40));
}

static void test_no_unlock_without_a_connection() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  const size_t n = loadCase("ok_mid_hire");
  TEST_ASSERT_NOT_EQUAL(KeyCheck::Ok, lock.unlock(key, n, 0));
  TEST_ASSERT_FALSE(lock.unlocked(0));
  TEST_ASSERT_FALSE(clock.anchored());
}

static void test_last_result_tracks_each_write() {
  AnchoredClock clock;
  HireLock lock(publicKey, vectors::kRobotSerial, clock);
  lock.connected();
  size_t n = loadCase("wrong_serial");
  lock.unlock(key, n, 0);
  TEST_ASSERT_EQUAL(KeyCheck::WrongSerial, lock.lastResult());
  n = loadCase("ok_mid_hire");
  lock.unlock(key, n, 0);
  TEST_ASSERT_EQUAL(KeyCheck::Ok, lock.lastResult());
  n = loadCase("bad_length_79");
  lock.unlock(key, n, 0);
  TEST_ASSERT_EQUAL(KeyCheck::BadLength, lock.lastResult());
  TEST_ASSERT_FALSE(lock.unlocked(0));
}

int main() {
  UNITY_BEGIN();
  RUN_TEST(test_every_vector_gives_its_expected_result);
  RUN_TEST(test_every_vector_decodes_to_its_fields);
  RUN_TEST(test_anchored_clock_is_unknown_until_anchored_and_then_counts);
  RUN_TEST(test_anchored_clock_survives_the_millisecond_counter_wrapping);
  RUN_TEST(test_lock_unlocks_with_a_good_key_and_anchors_the_clock);
  RUN_TEST(test_lock_locks_when_the_hire_ends);
  RUN_TEST(test_a_bad_key_does_not_anchor_the_clock_and_locks);
  RUN_TEST(test_a_later_key_is_checked_against_the_anchored_time);
  RUN_TEST(test_explicit_lock);
  RUN_TEST(test_result_codes_on_the_wire);
  RUN_TEST(test_a_disconnect_forgets_the_key_and_its_result);
  RUN_TEST(test_no_unlock_without_a_connection);
  RUN_TEST(test_last_result_tracks_each_write);
  return UNITY_END();
}
